import Foundation
import CryptoKit

// NFC pairing v2: constants, encodings and the cryptographic core.
//
// Normative reference: docs/security/NFC_PAIRING_V2.md (sections 3, 4, 5, 7 and 9). Every label, length and check
// order below follows that document; the vectors in nfc-pairing-kat.json (generated by
// scripts/kat/gen_nfc_pairing_kat.py, an independent implementation) pin the bytes. The iPhone only ever plays the
// reader; the functions that belong to the other role (`verifyReveal`, the card-side tag matching) exist so the shared
// vectors can be checked and so the tests have a counterpart, not because the phone answers these commands.
//
// Failure policy: every check returns or throws a `NfcPairingV2Failure` whose token is one of the result tokens of
// section 11. Nothing is stored here, nothing is logged here.

/// The result token of section 11, plus `cardError` for a status word the section does not name.
public enum NfcPairingV2Token: String, Equatable, Sendable, CaseIterable {
    case version
    case notArmed = "not_armed"
    case order
    case length
    case userId = "user_id"
    case x25519Zero = "x25519_zero"
    case kem
    case openFailed = "open_failed"
    case mac
    case signature
    case commitment
    case identitySelf = "identity_self"
    case identityInvalid = "identity_invalid"
    case peerIdentityChanged = "peer_identity_changed"
    case rtt
    case timeout
    case userRejected = "user_rejected"
    case peerRejected = "peer_rejected"
    case noCeremony = "no_ceremony"
    case storeFailed = "store_failed"
    case fieldLost = "field_lost"
    /// The other phone answered with a status word that has no token of its own in the document.
    case cardError = "card_error"
}

/// A failed ceremony: the token to log and the status word that came with it, when there was one.
public struct NfcPairingV2Failure: Error, Equatable, Sendable {
    public let token: NfcPairingV2Token
    public let statusWord: UInt16?

    public init(_ token: NfcPairingV2Token, statusWord: UInt16? = nil) {
        self.token = token
        self.statusWord = statusWord
    }
}

/// Constants of section 4.
public enum NfcPairingV2 {
    /// Protocol version byte (SELECT response, HELLO).
    public static let version: UInt8 = 0x02
    /// `F0 BC F1 07 3A 51 00`.
    public static let aid: Data = Data([0xF0, 0xBC, 0xF1, 0x07, 0x3A, 0x51, 0x00])
    /// Class byte of every command except SELECT.
    public static let proprietaryClass: UInt8 = 0x80

    public enum Instruction: UInt8, Sendable {
        case ekPut = 0x30
        case hello = 0x31
        case ctGet = 0x32
        case authCard = 0x33
        case reveal = 0x34
        case confirm = 0x35
        case finalize = 0x36
    }

    /// CONFIRM decision byte.
    public enum Decision: UInt8, Sendable {
        case confirm = 0x01
        case reject = 0x02
    }

    /// CONFIRM / FINALIZE state byte.
    public enum CardState: UInt8, Sendable {
        case pending = 0x00
        case confirmed = 0x01
        case rejected = 0x02
        case noCeremony = 0x03
        case aborted = 0x04
    }

    public static let chunkBytes: Int = 224
    public static let chunkCount: Int = 7
    public static let encapsulationKeyBytes: Int = 1568
    public static let ciphertextBytes: Int = 1568
    public static let nonceBytes: Int = 32
    public static let hashBytes: Int = 32
    public static let tagBytes: Int = 32
    public static let signatureBytes: Int = 64
    public static let identityKeyBytes: Int = 32
    public static let maxUserIdBytes: Int = 64
    public static let aeadTagBytes: Int = 16
    public static let helloCommandBytes: Int = 65
    public static let helloResponseBytes: Int = 64

    /// Largest AUTH_C plaintext: idBlock (33 + n) + signature + MAC.
    public static func cardPlaintextBytes(userIdBytes n: Int) -> Int { 33 + n + signatureBytes + tagBytes }
    /// Largest REVEAL plaintext: idBlock (33 + n) + nonce + signature + MAC.
    public static func readerPlaintextBytes(userIdBytes n: Int) -> Int { 33 + n + nonceBytes + signatureBytes + tagBytes }

    // Timing (milliseconds).
    public static let userConfirmationTimeoutMs: UInt64 = 120_000
    public static let confirmPollIntervalMs: UInt64 = 250
    public static let confirmPollBudgetMs: UInt64 = 20_000
    /// Initial value of the HELLO round-trip limit; the measured value is always logged.
    public static let helloRoundTripLimitMs: UInt64 = 500
    /// Time budget of the whole first tap, well inside the roughly 60 s a CoreNFC reader session lasts.
    public static let firstTapBudgetMs: UInt64 = 30_000

    /// The labels of section 4, as bytes.
    public enum Label {
        public static let transcript = Data("qaudion-nfc-v2/transcript".utf8)
        public static let commit = Data("qaudion-nfc-v2/commit".utf8)
        public static let transcriptCard = Data("qaudion-nfc-v2/transcript-card".utf8)
        public static let transcriptReader = Data("qaudion-nfc-v2/transcript-reader".utf8)
        public static let encCard = Data("qaudion-nfc-v2/enc-card".utf8)
        public static let encReader = Data("qaudion-nfc-v2/enc-reader".utf8)
        public static let macCard = Data("qaudion-nfc-v2/mac-card".utf8)
        public static let macReader = Data("qaudion-nfc-v2/mac-reader".utf8)
        public static let sigCard = Data("qaudion-nfc-v2/sig-card".utf8)
        public static let sigReader = Data("qaudion-nfc-v2/sig-reader".utf8)
        public static let confirmCard = Data("qaudion-nfc-v2/confirm-card".utf8)
        public static let confirmReader = Data("qaudion-nfc-v2/confirm-reader".utf8)
        public static let sas = Data("qaudion-nfc-v2/sas".utf8)
        public static let psk = Data("qaudion-nfc-v2/psk".utf8)
        public static let userConfirmed = Data("qaudion-nfc-v2/user-confirmed".utf8)
        public static let userRejected = Data("qaudion-nfc-v2/user-rejected".utf8)
        public static let finalize = Data("qaudion-nfc-v2/finalize".utf8)
        public static let log = Data("qaudion-nfc-v2/log".utf8)
    }

    /// `[A-Za-z0-9._-]` (section 4).
    static func isUserIdByte(_ byte: UInt8) -> Bool {
        (byte >= 0x41 && byte <= 0x5A) || (byte >= 0x61 && byte <= 0x7A) || (byte >= 0x30 && byte <= 0x39)
            || byte == 0x2E || byte == 0x5F || byte == 0x2D
    }
}

/// An identity as it travels sealed: `idPub[32] ‖ u8(n) ‖ userId[n]`.
public struct NfcPairingV2Identity: Equatable, Sendable {
    public let publicKey: Data
    /// Empty when the phone has no account id (`n = 0`).
    public let userId: String
    /// The encoded block (33 + n bytes).
    public let block: Data

    /// Builds the block of a local identity. Throws `.length` / `.userId` for a key or id the grammar refuses.
    public init(publicKey: Data, userId: String) throws {
        guard publicKey.count == NfcPairingV2.identityKeyBytes else { throw NfcPairingV2Failure(.length) }
        let idBytes = Array(userId.utf8)
        guard idBytes.count <= NfcPairingV2.maxUserIdBytes else { throw NfcPairingV2Failure(.length) }
        guard idBytes.allSatisfy(NfcPairingV2.isUserIdByte) else { throw NfcPairingV2Failure(.userId) }
        var block = Data(publicKey)
        block.append(UInt8(idBytes.count))
        block.append(contentsOf: idBytes)
        self.publicKey = Data(publicKey)
        self.userId = userId
        self.block = block
    }
}

/// The cryptographic functions of the protocol. Pure; nothing here touches the vault or the system.
public enum NfcPairingV2Crypto {

    // MARK: - Encodings

    /// `u32be(len(x)) ‖ x`.
    public static func lp32(_ data: Data) -> Data {
        var out = Data()
        let n = UInt32(truncatingIfNeeded: data.count)
        out.append(UInt8((n >> 24) & 0xFF))
        out.append(UInt8((n >> 16) & 0xFF))
        out.append(UInt8((n >> 8) & 0xFF))
        out.append(UInt8(n & 0xFF))
        out.append(data)
        return out
    }

    /// Splits a decrypted plaintext into its identity block and the bytes after it.
    /// Order of the checks: block length, `n <= 64`, the userId alphabet (section 4).
    public static func parseIdentityBlock(_ plaintext: Data) throws -> (identity: NfcPairingV2Identity, rest: Data) {
        let bytes = [UInt8](plaintext)
        guard bytes.count >= 33 else { throw NfcPairingV2Failure(.length) }
        let n = Int(bytes[32])
        guard n <= NfcPairingV2.maxUserIdBytes, bytes.count >= 33 + n else { throw NfcPairingV2Failure(.length) }
        let idBytes = Array(bytes[33..<(33 + n)])
        guard idBytes.allSatisfy(NfcPairingV2.isUserIdByte) else { throw NfcPairingV2Failure(.userId) }
        let userId = String(decoding: idBytes, as: UTF8.self)
        let identity = try NfcPairingV2Identity(publicKey: Data(bytes[0..<32]), userId: userId)
        return (identity, Data(bytes[(33 + n)...]))
    }

    // MARK: - Commitment and transcripts

    /// `commit_R = SHA-256(L_COMMIT ‖ nonce_R ‖ lp32(idBlock_R))`.
    public static func commitment(readerNonce: Data, readerIdentityBlock: Data) -> Data {
        sha256(NfcPairingV2.Label.commit + readerNonce + lp32(readerIdentityBlock))
    }

    /// `TH1 = SHA-256(L_TH1 ‖ lp32(selectData) ‖ lp32(ek_R) ‖ lp32(helloCmd) ‖ lp32(helloResp) ‖ lp32(ct_C))`.
    public static func transcriptHash1(selectData: Data, encapsulationKey: Data, helloCommand: Data,
                                       helloResponse: Data, ciphertext: Data) -> Data {
        var input = NfcPairingV2.Label.transcript
        input.append(lp32(selectData))
        input.append(lp32(encapsulationKey))
        input.append(lp32(helloCommand))
        input.append(lp32(helloResponse))
        input.append(lp32(ciphertext))
        return sha256(input)
    }

    /// `TH_C = SHA-256(L_TH_C ‖ TH1 ‖ lp32(idBlock_C))`.
    public static func transcriptHashCard(th1: Data, cardIdentityBlock: Data) -> Data {
        sha256(NfcPairingV2.Label.transcriptCard + th1 + lp32(cardIdentityBlock))
    }

    /// `TH_R = SHA-256(L_TH_R ‖ TH_C ‖ lp32(idBlock_R) ‖ nonce_R)`.
    public static func transcriptHashReader(thCard: Data, readerIdentityBlock: Data, readerNonce: Data) -> Data {
        sha256(NfcPairingV2.Label.transcriptReader + thCard + lp32(readerIdentityBlock) + readerNonce)
    }

    /// `lowercase hex of the first 4 bytes of SHA-256(L_LOG ‖ TH1)`.
    public static func logTag(th1: Data) -> String {
        sha256(NfcPairingV2.Label.log + th1).prefix(4).map { String(format: "%02x", $0) }.joined()
    }

    // MARK: - Key schedule

    /// The keys of stage 1. `zeroize()` as soon as stage 2 is derived or the ceremony fails.
    public struct Stage1 {
        public private(set) var prk1: Data
        public private(set) var encCard: Data
        public private(set) var encReader: Data
        public private(set) var macCard: Data
        public private(set) var macReader: Data

        public mutating func zeroize() {
            CryptoConstants.zeroize(&prk1)
            CryptoConstants.zeroize(&encCard)
            CryptoConstants.zeroize(&encReader)
            CryptoConstants.zeroize(&macCard)
            CryptoConstants.zeroize(&macReader)
            prk1 = Data(); encCard = Data(); encReader = Data(); macCard = Data(); macReader = Data()
        }
    }

    /// `PRK1 = HKDF-Extract(salt = TH1, IKM = ss_kem ‖ ss_x)` and the four stage-1 keys.
    public static func deriveStage1(th1: Data, kemSharedSecret: Data, x25519SharedSecret: Data) throws -> Stage1 {
        guard th1.count == NfcPairingV2.hashBytes, kemSharedSecret.count == 32, x25519SharedSecret.count == 32 else {
            throw NfcPairingV2Failure(.length)
        }
        var ikm = kemSharedSecret + x25519SharedSecret
        defer { CryptoConstants.zeroize(&ikm) }
        let prk = HKDF<SHA256>.extract(inputKeyMaterial: SymmetricKey(data: ikm), salt: th1)
        return Stage1(prk1: bytes(of: prk),
                      encCard: expand(prk, NfcPairingV2.Label.encCard, 32),
                      encReader: expand(prk, NfcPairingV2.Label.encReader, 32),
                      macCard: expand(prk, NfcPairingV2.Label.macCard, 32),
                      macReader: expand(prk, NfcPairingV2.Label.macReader, 32))
    }

    /// The keys, code and tags of stage 2.
    public struct Stage2 {
        public private(set) var confirmKeyReader: Data
        public private(set) var confirmKeyCard: Data
        public private(set) var sasBytes: Data
        public private(set) var sas: String
        public private(set) var psk: Data
        /// `HMAC(K_confirm_R, L_CONFIRMED)`: what the reader sends in CONFIRM.
        public private(set) var confirmReader: Data
        /// `HMAC(K_confirm_R, L_REJECTED)`.
        public private(set) var rejectReader: Data
        /// `HMAC(K_confirm_R, L_FINAL)`: what the reader sends in FINALIZE.
        public private(set) var finalizeReader: Data
        /// `HMAC(K_confirm_C, L_CONFIRMED)`: what the card answers once it stored the key.
        public private(set) var confirmCard: Data
        /// `HMAC(K_confirm_C, L_REJECTED)`.
        public private(set) var rejectCard: Data

        public mutating func zeroize() {
            CryptoConstants.zeroize(&confirmKeyReader)
            CryptoConstants.zeroize(&confirmKeyCard)
            CryptoConstants.zeroize(&sasBytes)
            CryptoConstants.zeroize(&psk)
            CryptoConstants.zeroize(&confirmReader)
            CryptoConstants.zeroize(&rejectReader)
            CryptoConstants.zeroize(&finalizeReader)
            CryptoConstants.zeroize(&confirmCard)
            CryptoConstants.zeroize(&rejectCard)
            confirmKeyReader = Data(); confirmKeyCard = Data(); sasBytes = Data(); psk = Data()
            confirmReader = Data(); rejectReader = Data(); finalizeReader = Data()
            confirmCard = Data(); rejectCard = Data()
            sas = ""
        }
    }

    /// `PRK2 = HKDF-Extract(salt = TH_R, IKM = PRK1 ‖ nonce_R ‖ nonce_C)`, then the confirmation keys, the SAS bytes
    /// and the PSK.
    public static func deriveStage2(prk1: Data, thReader: Data, readerNonce: Data, cardNonce: Data) throws -> Stage2 {
        guard prk1.count == 32, thReader.count == NfcPairingV2.hashBytes,
              readerNonce.count == NfcPairingV2.nonceBytes, cardNonce.count == NfcPairingV2.nonceBytes else {
            throw NfcPairingV2Failure(.length)
        }
        var ikm = prk1 + readerNonce + cardNonce
        defer { CryptoConstants.zeroize(&ikm) }
        let prk = HKDF<SHA256>.extract(inputKeyMaterial: SymmetricKey(data: ikm), salt: thReader)
        let confirmKeyReader = expand(prk, NfcPairingV2.Label.confirmReader, 32)
        let confirmKeyCard = expand(prk, NfcPairingV2.Label.confirmCard, 32)
        let sasBytes = expand(prk, NfcPairingV2.Label.sas, 8)
        let code = ProximityPairingCrypto.sas(fromBytes: sasBytes)
        guard code.count == 6 else { throw NfcPairingV2Failure(.length) }
        return Stage2(confirmKeyReader: confirmKeyReader, confirmKeyCard: confirmKeyCard,
                      sasBytes: sasBytes, sas: code,
                      psk: expand(prk, NfcPairingV2.Label.psk, 32),
                      confirmReader: hmac(confirmKeyReader, NfcPairingV2.Label.userConfirmed),
                      rejectReader: hmac(confirmKeyReader, NfcPairingV2.Label.userRejected),
                      finalizeReader: hmac(confirmKeyReader, NfcPairingV2.Label.finalize),
                      confirmCard: hmac(confirmKeyCard, NfcPairingV2.Label.userConfirmed),
                      rejectCard: hmac(confirmKeyCard, NfcPairingV2.Label.userRejected))
    }

    // MARK: - Proofs

    /// `L_SIG_C ‖ TH_C`.
    public static func cardSignaturePayload(thCard: Data) -> Data { NfcPairingV2.Label.sigCard + thCard }
    /// `L_SIG_R ‖ TH_R`.
    public static func readerSignaturePayload(thReader: Data) -> Data { NfcPairingV2.Label.sigReader + thReader }

    /// `HMAC-SHA256(K_mac, TH)`.
    public static func transcriptMac(key: Data, transcriptHash: Data) -> Data { hmac(key, transcriptHash) }

    /// Seals the reader's REVEAL payload: `Seal(K_enc_R, aad = TH_C, idBlock_R ‖ nonce_R ‖ sig_R ‖ mac_R)`.
    /// The signature is made here (CryptoKit signs with randomness: the sealed bytes differ between runs, and the
    /// signature is in no transcript). Every key seals exactly one message: call this once per ceremony and keep
    /// the bytes if the command has to be sent again.
    public static func sealReaderReveal(identity: NfcPairingV2Identity, signingPrivateKey: Data, readerNonce: Data,
                                        thCard: Data, thReader: Data, stage1: Stage1) throws -> Data {
        let signature = try ProximityPairingCrypto.sign(readerSignaturePayload(thReader: thReader),
                                                        signingPrivateKey: signingPrivateKey)
        let mac = transcriptMac(key: stage1.macReader, transcriptHash: thReader)
        var plaintext = identity.block
        plaintext.append(readerNonce)
        plaintext.append(signature)
        plaintext.append(mac)
        defer { CryptoConstants.zeroize(&plaintext) }
        return try ProximityPairingCrypto.aeadSeal(plaintext, key: stage1.encReader, transcriptHash: thCard)
    }

    /// Seals the card's AUTH_C payload (the card's role; used by the test double and the vectors).
    static func sealCardAuth(identity: NfcPairingV2Identity, signingPrivateKey: Data, th1: Data,
                             stage1: Stage1) throws -> Data {
        let thCard = transcriptHashCard(th1: th1, cardIdentityBlock: identity.block)
        let signature = try ProximityPairingCrypto.sign(cardSignaturePayload(thCard: thCard),
                                                        signingPrivateKey: signingPrivateKey)
        var plaintext = identity.block
        plaintext.append(signature)
        plaintext.append(transcriptMac(key: stage1.macCard, transcriptHash: thCard))
        defer { CryptoConstants.zeroize(&plaintext) }
        return try ProximityPairingCrypto.aeadSeal(plaintext, key: stage1.encCard, transcriptHash: th1)
    }

    /// The card's identity, proven.
    public struct VerifiedCard: Equatable, Sendable {
        public let identity: NfcPairingV2Identity
        /// `TH_C`, the transcript hash the card signed.
        public let thCard: Data
    }

    /// Reader side, on the AUTH_C response, in the order of section 9: open, parse, identity checks, MAC, signature,
    /// then the pinned-key check when a contact-targeted re-pairing supplied the key stored for that contact.
    /// Nothing about the peer is shown or logged before this returns.
    public static func verifyCardAuth(sealed: Data, stage1: Stage1, th1: Data, ownIdentityKey: Data,
                                      pinnedPeerKey: Data?) throws -> VerifiedCard {
        let plaintext = try open(sealed, key: stage1.encCard, aad: th1)
        let (identity, rest) = try parseIdentityBlock(plaintext)
        guard rest.count == NfcPairingV2.signatureBytes + NfcPairingV2.tagBytes else { throw NfcPairingV2Failure(.length) }
        try checkPeerIdentityKey(identity.publicKey, ownKey: ownIdentityKey)
        let signature = rest.prefix(NfcPairingV2.signatureBytes)
        let mac = rest.suffix(NfcPairingV2.tagBytes)
        let thCard = transcriptHashCard(th1: th1, cardIdentityBlock: identity.block)
        guard ProximityPairingCrypto.constantTimeEquals(
            transcriptMac(key: stage1.macCard, transcriptHash: thCard), Data(mac)) else {
            throw NfcPairingV2Failure(.mac)
        }
        guard verifySignature(Data(signature), payload: cardSignaturePayload(thCard: thCard),
                              publicKey: identity.publicKey) else {
            throw NfcPairingV2Failure(.signature)
        }
        if let pinned = pinnedPeerKey {
            guard ProximityPairingCrypto.constantTimeEquals(pinned, identity.publicKey) else {
                throw NfcPairingV2Failure(.peerIdentityChanged)
            }
        }
        return VerifiedCard(identity: identity, thCard: thCard)
    }

    /// Card side, on the REVEAL command (section 9): open, parse, commitment, identity checks, MAC, signature.
    /// The phone never plays this role; it is here for the shared vectors and the test double.
    static func verifyReveal(sealed: Data, stage1: Stage1, thCard: Data, readerCommitment: Data,
                             ownIdentityKey: Data) throws -> (identity: NfcPairingV2Identity, nonce: Data, thReader: Data) {
        let plaintext = try open(sealed, key: stage1.encReader, aad: thCard)
        let (identity, rest) = try parseIdentityBlock(plaintext)
        guard rest.count == NfcPairingV2.nonceBytes + NfcPairingV2.signatureBytes + NfcPairingV2.tagBytes else {
            throw NfcPairingV2Failure(.length)
        }
        let nonce = Data(rest.prefix(NfcPairingV2.nonceBytes))
        let signature = Data(rest.dropFirst(NfcPairingV2.nonceBytes).prefix(NfcPairingV2.signatureBytes))
        let mac = Data(rest.suffix(NfcPairingV2.tagBytes))
        guard ProximityPairingCrypto.constantTimeEquals(
            commitment(readerNonce: nonce, readerIdentityBlock: identity.block), readerCommitment) else {
            throw NfcPairingV2Failure(.commitment)
        }
        try checkPeerIdentityKey(identity.publicKey, ownKey: ownIdentityKey)
        let thReader = transcriptHashReader(thCard: thCard, readerIdentityBlock: identity.block, readerNonce: nonce)
        guard ProximityPairingCrypto.constantTimeEquals(
            transcriptMac(key: stage1.macReader, transcriptHash: thReader), mac) else {
            throw NfcPairingV2Failure(.mac)
        }
        guard verifySignature(signature, payload: readerSignaturePayload(thReader: thReader),
                              publicKey: identity.publicKey) else {
            throw NfcPairingV2Failure(.signature)
        }
        return (identity, nonce, thReader)
    }

    /// Identity checks of sections 3 and 9: not the phone's own key (`identity_self`), a canonical encoding of a
    /// point in the prime-order subgroup (`identity_invalid`).
    static func checkPeerIdentityKey(_ key: Data, ownKey: Data) throws {
        if ProximityPairingCrypto.constantTimeEquals(key, ownKey) { throw NfcPairingV2Failure(.identitySelf) }
        guard Ed25519PrimeOrderCheck.isAcceptableIdentityKey(key) else { throw NfcPairingV2Failure(.identityInvalid) }
    }

    // MARK: - Ed25519 verification (section 3)

    /// l, the group order, as 32 little-endian bytes.
    private static let groupOrderLE: [UInt8] = Ed25519PrimeOrderCheck.Curve.groupOrderLimbs.flatMap { limb -> [UInt8] in
        [UInt8(limb & 0xFF), UInt8((limb >> 8) & 0xFF), UInt8((limb >> 16) & 0xFF), UInt8((limb >> 24) & 0xFF)]
    }

    /// RFC 8032 section 5.1.7 verification with the strictness the document asks for: `S < l`, a canonical `R` in the
    /// prime-order subgroup, a peer key already accepted by `checkPeerIdentityKey`, and then the library's own
    /// equation. With `A` and `R` both in the prime-order subgroup the cofactored and the cofactorless equations
    /// agree, so two platforms with different library choices cannot disagree about a signature.
    public static func verifySignature(_ signature: Data, payload: Data, publicKey: Data) -> Bool {
        guard signature.count == NfcPairingV2.signatureBytes, publicKey.count == NfcPairingV2.identityKeyBytes,
              !payload.isEmpty else { return false }
        let bytes = [UInt8](signature)
        let s = Array(bytes[32..<64])
        guard isLess(s, than: groupOrderLE) else { return false }
        guard Ed25519PrimeOrderCheck.isAcceptableIdentityKey(Data(bytes[0..<32])) else { return false }
        return ProximityPairingCrypto.verify(signature: signature, payload: payload, signingPublicKey: publicKey)
    }

    private static func isLess(_ a: [UInt8], than b: [UInt8]) -> Bool {
        var i = 31
        while i >= 0 {
            if a[i] < b[i] { return true }
            if a[i] > b[i] { return false }
            i -= 1
        }
        return false
    }

    // MARK: - Tags

    /// True when `presented` equals the expected tag, in constant time.
    public static func tagMatches(_ presented: Data, _ expected: Data) -> Bool {
        ProximityPairingCrypto.constantTimeEquals(presented, expected)
    }

    /// Card side: matches a presented tag against every candidate it holds, without an early exit. The index of the
    /// candidate that matched, if any.
    static func matchTag(_ presented: Data, candidates: [Data]) -> Int? {
        var found: Int?
        for (index, candidate) in candidates.enumerated() where ProximityPairingCrypto.constantTimeEquals(presented, candidate) {
            found = found ?? index
        }
        return found
    }

    // MARK: - Sealed boxes

    private static func open(_ sealed: Data, key: Data, aad: Data) throws -> Data {
        do {
            return try ProximityPairingCrypto.aeadOpen(sealed, key: key, transcriptHash: aad)
        } catch {
            throw NfcPairingV2Failure(.openFailed)
        }
    }

    // MARK: - Primitives

    static func sha256(_ data: Data) -> Data { Data(SHA256.hash(data: data)) }

    static func hmac(_ key: Data, _ message: Data) -> Data {
        Data(HMAC<SHA256>.authenticationCode(for: message, using: SymmetricKey(data: key)))
    }

    private static func bytes(of prk: HashedAuthenticationCode<SHA256>) -> Data {
        prk.withUnsafeBytes { Data($0) }
    }

    private static func expand(_ prk: HashedAuthenticationCode<SHA256>, _ label: Data, _ count: Int) -> Data {
        HKDF<SHA256>.expand(pseudoRandomKey: prk, info: label, outputByteCount: count).withUnsafeBytes { Data($0) }
    }
}

// MARK: - APDUs

/// A command APDU of the protocol: header, optional data, optional expected length (1...256, 256 is Le = 0x00).
struct NfcApduCommand: Equatable, Sendable {
    let cla: UInt8
    let ins: UInt8
    let p1: UInt8
    let p2: UInt8
    let data: Data
    let expectedLength: Int?

    /// The wire bytes: `CLA INS P1 P2 [Lc data] [Le]`.
    var encoded: Data {
        var out = Data([cla, ins, p1, p2])
        if !data.isEmpty {
            out.append(UInt8(data.count))
            out.append(data)
        }
        if let le = expectedLength {
            out.append(UInt8(truncatingIfNeeded: le == 256 ? 0 : le))
        }
        return out
    }

    /// `00 A4 04 00 07 AID 00`.
    static var select: NfcApduCommand {
        NfcApduCommand(cla: 0x00, ins: 0xA4, p1: 0x04, p2: 0x00, data: NfcPairingV2.aid, expectedLength: 256)
    }

    static func proprietary(_ ins: NfcPairingV2.Instruction, p1: UInt8 = 0, p2: UInt8 = 0, data: Data = Data(),
                            expectedLength: Int? = nil) -> NfcApduCommand {
        NfcApduCommand(cla: NfcPairingV2.proprietaryClass, ins: ins.rawValue, p1: p1, p2: p2, data: data,
                       expectedLength: expectedLength)
    }
}

/// A response APDU: the data bytes and the status word.
struct NfcApduResponse: Equatable, Sendable {
    let data: Data
    let statusWord: UInt16

    var isOk: Bool { statusWord == 0x9000 }
}

/// Why a transceive did not produce a response.
enum NfcTransportError: Error, Equatable, Sendable {
    /// The session was invalidated or the tag connection was lost: never a rejection.
    case fieldLost
    case timeout
}

/// One ISO 7816 exchange partner. CoreNFC provides it on the phone, a fake provides it in the tests.
protocol NfcIso7816Transport: AnyObject {
    func transceive(_ command: NfcApduCommand) async throws -> NfcApduResponse
}
